"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

interface OrderRow {
  _id: string;
  orderNumber: string;
  customer?: { firstName?: string; lastName?: string; email?: string; phone?: string; dni?: string; address?: string; city?: string; province?: string; postalCode?: string };
  items?: { name?: string; quantity?: number }[];
  status?: string;
  paymentStatus?: string;
  fulfillmentStatus?: string;
  total?: number;
  tracking?: string;
  stockIssue?: boolean;
  stockIssueReason?: string;
  stockIssueAt?: string;
  createdAt?: string;
}

const FULFILLMENT_LABELS: Record<string, string> = {
  pending: "Pendiente de envío a proveedor",
  processing: "Enviando a proveedor…",
  blocked: "Bloqueado (falta contrato/datos)",
  failed: "Falló el envío al proveedor",
  submitted: "Enviado al proveedor",
  confirmed: "Confirmado por proveedor",
  preparing: "Proveedor preparando",
  shipped: "Enviado",
  in_transit: "En tránsito",
  delivered: "Entregado",
  cancelled: "Cancelado",
};

// Arma el texto para pegar en Dropsheable → Venta Externa → Nueva Venta Manual.
function buildDropsheableClipboardText(order: OrderRow) {
  const customer = order.customer ?? {};
  const items = order.items ?? [];
  const lines = [
    `Pedido AVG: ${order.orderNumber}`,
    "",
    "Producto(s):",
    ...(items.length ? items.map((item) => `- ${item.name ?? "Producto"} x${item.quantity ?? 1}`) : ["- (sin items registrados)"]),
    "",
    `Nombre: ${customer.firstName ?? ""}`,
    `Apellido: ${customer.lastName ?? ""}`,
    `DNI: ${customer.dni ?? "<<COMPLETAR - pedido anterior al alta del campo DNI>>"}`,
    `Teléfono: ${customer.phone ?? ""}`,
    `Email: ${customer.email ?? ""}`,
    `Dirección: ${customer.address ?? ""}`,
    `Localidad: ${customer.city ?? ""}`,
    `Provincia: ${customer.province ?? ""}`,
    `Código Postal: ${customer.postalCode ?? ""}`,
    `Observaciones: Pedido AVG ${order.orderNumber} — pago aprobado`,
  ];
  return lines.join("\n");
}

export default function OperationsPage() {
  const [orders, setOrders] = useState<OrderRow[]>([]);
  const [trackingMap, setTrackingMap] = useState<Record<string, string>>({});
  const [message, setMessage] = useState("");
  const [retryingId, setRetryingId] = useState<string | null>(null);
  const [copiedId, setCopiedId] = useState<string | null>(null);

  const copyForDropsheable = async (order: OrderRow) => {
    try {
      await navigator.clipboard.writeText(buildDropsheableClipboardText(order));
      setCopiedId(order._id);
      setMessage("Datos copiados. Pegalos en Dropsheable → Venta Externa → Nueva Venta Manual.");
      setTimeout(() => setCopiedId((current) => (current === order._id ? null : current)), 3000);
    } catch {
      setMessage("No se pudo copiar. Copiá los datos manualmente desde el pedido.");
    }
  };

  const loadOrders = async () => {
    try {
      const response = await fetch("/api/admin/orders");
      const data = await response.json();
      setOrders(data.orders ?? []);
    } catch {
      setMessage("No se pudieron cargar los pedidos");
    }
  };

  useEffect(() => {
    queueMicrotask(() => { void loadOrders(); });
  }, []);

  const updateStatus = async (orderId: string, status: string) => {
    try {
      const response = await fetch("/api/admin/orders", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: orderId, status }),
      });
      const data = await response.json();
      if (data.success) {
        setMessage("Estado actualizado");
        await loadOrders();
      }
    } catch {
      setMessage("No se pudo actualizar el pedido");
    }
  };

  const saveTracking = async (orderId: string) => {
    try {
      const tracking = trackingMap[orderId] ?? "";
      const response = await fetch("/api/admin/orders", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ id: orderId, tracking, status: "shipped" }),
      });
      const data = await response.json();
      if (data.success) {
        setMessage("Tracking actualizado");
        await loadOrders();
      }
    } catch {
      setMessage("No se pudo guardar el tracking");
    }
  };

  const retryStock = async (orderId: string) => {
    if (retryingId || !window.confirm("¿Reintentar la aplicación de stock? Sólo hacelo luego de confirmar disponibilidad.")) return;
    try {
      setRetryingId(orderId);
      const response = await fetch(`/api/admin/orders/${orderId}/stock/retry`, { method: "POST", headers: { "Content-Type": "application/json" } });
      const data = await response.json() as { success?: boolean; result?: { outcome?: string } };
      if (!response.ok || !data.success) throw new Error(data.result?.outcome ?? "No se pudo aplicar el stock");
      setOrders((current) => current.map((order) => order._id === orderId ? { ...order, stockIssue: false, stockIssueReason: undefined, status: "paid" } : order));
      setMessage(data.result?.outcome === "already_applied" ? "El stock ya estaba aplicado" : "Stock aplicado correctamente");
    } catch (error) { setMessage(error instanceof Error ? `Reintento no aplicado: ${error.message}` : "Reintento no aplicado"); }
    finally { setRetryingId(null); }
  };

  return (
    <main className="ui-admin-main">
      <div className="mx-auto max-w-7xl">
        <div className="ui-surface ui-admin-header">
          <div>
            <p className="text-sm font-medium uppercase tracking-[0.3em] text-neutral-500">Centro operativo</p>
            <h1 className="mt-2 text-3xl font-semibold text-neutral-950">Gestión de pedidos</h1>
            <p className="mt-2 text-sm text-neutral-600">Controla el estado de los pedidos, el proveedor y el tracking desde un solo lugar.</p>
          </div>
          <Link href="/admin" className="ui-button-secondary">Volver al panel</Link>
        </div>

        {message ? <div className="ui-card mb-6 p-4 text-sm text-neutral-700">{message}</div> : null}

        <div className="ui-surface overflow-hidden">
          <div className="overflow-x-auto">
            <table className="ui-admin-table">
              <thead>
                <tr>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Pedido</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Cliente</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Estado</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Proveedor</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Tracking</th>
                  <th className="px-4 py-3 text-left text-xs font-semibold uppercase tracking-[0.2em] text-neutral-500">Acciones</th>
                </tr>
              </thead>
              <tbody>
                {orders.map((order) => (
                  <tr key={order._id} className="align-top">
                    <td className="px-4 py-4 text-sm text-neutral-900">
                      <div className="font-semibold">{order.orderNumber}</div>
                      <div className="mt-1 text-xs text-neutral-500">{order.createdAt ? new Date(order.createdAt).toLocaleDateString("es-AR") : "Reciente"}</div>
                    </td>
                    <td className="px-4 py-4 text-sm text-neutral-700">
                      <div>{order.customer?.firstName ? `${order.customer.firstName} ${order.customer.lastName ?? ""}`.trim() : "Cliente"}</div>
                      <div className="mt-1 text-xs text-neutral-500">{order.customer?.email ?? "Sin email"}</div>
                    </td>
                    <td className="px-4 py-4 text-sm text-neutral-700">
                      <select value={order.status ?? order.paymentStatus ?? "pending"} onChange={(event) => updateStatus(String(order._id), event.target.value)} className="px-3 py-2 text-sm">
                        <option value="pending">Pendiente proveedor</option>
                        <option value="paid">Pago aprobado</option>
                        <option value="processing">Preparando</option>
                        <option value="shipped">Enviado</option>
                        <option value="delivered">Entregado</option>
                        <option value="cancelled">Cancelado</option>
                      </select>
                    </td>
                    <td className="px-4 py-4 text-sm text-neutral-700">
                      <div className="mb-2 text-xs font-medium text-neutral-600">{FULFILLMENT_LABELS[order.fulfillmentStatus ?? ""] ?? (order.fulfillmentStatus ?? "—")}</div>
                      {order.paymentStatus === "approved" ? (
                        <button type="button" onClick={() => copyForDropsheable(order)} className="ui-button-secondary min-h-0 px-3 py-2 text-xs">
                          {copiedId === order._id ? "Copiado ✓" : "Copiar para Dropsheable"}
                        </button>
                      ) : null}
                    </td>
                    <td className="px-4 py-4 text-sm text-neutral-700">
                      <input className="w-full px-3 py-2" value={trackingMap[order._id] ?? order.tracking ?? ""} onChange={(event) => setTrackingMap((prev) => ({ ...prev, [order._id]: event.target.value }))} placeholder="Tracking" />
                    </td>
                    <td className="px-4 py-4 text-sm text-neutral-700">
                      {order.stockIssue ? <div className="mb-3 rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-900"><strong>Incidencia de stock:</strong> {order.stockIssueReason ?? "Sin información"}<br />{order.stockIssueAt ? new Date(order.stockIssueAt).toLocaleString("es-AR") : "Fecha no disponible"}<button type="button" disabled={retryingId !== null} onClick={() => retryStock(order._id)} className="ui-button-primary mt-2 min-h-0 px-3 py-2 disabled:opacity-50">{retryingId === order._id ? "Reintentando…" : "Reintentar aplicación de stock"}</button></div> : null}
                      <button type="button" onClick={() => saveTracking(order._id)} className="ui-button-primary min-h-0 px-3 py-2">Guardar</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </main>
  );
}
